import struct

from . import native
from .errors import WPipeError

__all__ = [
    "CLOSED_ERRORS",
    "DEFAULT_BUFFER_SIZE",
    "HEADER_SIZE",
    "MAX_PAYLOAD_SIZE",
    "FrameBuffer",
    "FramedChannel",
    "chunk_size",
    "encode_frame",
    "frame_header",
    "parse_header",
    "resolve_name",
]

#: 长度前缀的字节数（小端 uint32）。
HEADER_SIZE = 4
_HEADER = struct.Struct("<I")

#: 单个 payload 的最大字节数（uint32 上限）。
MAX_PAYLOAD_SIZE = 0xFFFFFFFF

DEFAULT_BUFFER_SIZE = 4096

